    VCM.add(COV_REFERENCE_FRAME: COV_REFERENCE_FRAME, &fbb)
    VCM.addVectorOf(COVARIANCE: COVARIANCE, &fbb)
    VCM.add(USER_DEFINED_BIP_0044_TYPE: USER_DEFINED_BIP_0044_TYPE, &fbb)
